fn main() {
    for i in 1..=5 {
        println!("For: {}", i);
    }

    let mut n = 10;
    while n > 0 {
        println!("While: {}", n);
        n -= 1;
    }

    let mut i = 0;
    loop {
        println!("Tick...");
        i += 1;
        if i == 3 {
